INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019f-am-25','exam-sg','DNS水責め攻撃','standard','single_choice','【2019年度 令和元年秋期 午前 問25】攻撃者が，多数のオープンリゾルバに対して，“あるドメイン”の実在しないランダムなサブドメインを多数問い合わせる攻撃（ランダムサブドメイン攻撃）を仕掛け，多数のオープンリゾルバが応答した。このときに発生する事象はどれか。','[{"id":"a","text":"“あるドメイン”を管理する権威DNSサーバに対して負荷が掛かる。"},{"id":"b","text":"“あるドメイン”を管理する権威DNSサーバに登録されているDNS情報が改ざんされる。"},{"id":"c","text":"オープンリゾルバが保持するDNSキャッシュに不正な値を注入される。"},{"id":"d","text":"オープンリゾルバが保持するゾーン情報を不正に入手される。"}]','"a"','ランダムサブドメイン攻撃（DNS水責め攻撃）では，キャッシュにない名前の問い合わせが権威DNSサーバへ集中し，サーバ負荷が増大する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-26','exam-sg','ハイブリッド暗号方式','standard','single_choice','【2019年度 令和元年秋期 午前 問26】手順に示す電子メールの送受信によって得られるセキュリティ上の効果はどれか。本文を共通鍵暗号方式で暗号化し，共通鍵を受信者の公開鍵で暗号化して送信し，受信者は自分の秘密鍵で共通鍵を復号して本文を復号する。','[{"id":"a","text":"送信者による電子メールの送達確認"},{"id":"b","text":"送信者のなりすましの検出"},{"id":"c","text":"電子メールの本文の改ざん箇所の修正"},{"id":"d","text":"電子メールの本文の内容の漏えいの防止"}]','"d"','これはハイブリッド暗号方式であり，受信者だけが秘密鍵で共通鍵を復号できるため，本文の機密性を確保する。暗号化だけでは送達確認や送信者認証，改ざん箇所の修正はできない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-27','exam-sg','PCI DSS','standard','single_choice','【2019年度 令和元年秋期 午前 問27】クレジットカードなどのカード会員データのセキュリティ強化を目的として制定され，技術面及び運用面の要件を定めたものはどれか。','[{"id":"a","text":"ISMS適合性評価制度"},{"id":"b","text":"PCI DSS"},{"id":"c","text":"特定個人情報保護評価"},{"id":"d","text":"プライバシーマーク制度"}]','"b"','PCI DSSはカード会員データを保護するためのセキュリティ基準で，技術面と運用面の要件を定める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-28','exam-sg','SMTP-AUTH','standard','single_choice','【2019年度 令和元年秋期 午前 問28】電子メールをドメインAの送信者がドメインBの宛先に送信するとき，送信者をドメインAのメールサーバで認証するためのものはどれか。','[{"id":"a","text":"APOP"},{"id":"b","text":"POP3S"},{"id":"c","text":"S/MIME"},{"id":"d","text":"SMTP-AUTH"}]','"d"','SMTP-AUTHはメール送信時に送信者をメールサーバで認証する仕組み。APOPとPOP3Sは主に受信時の認証・暗号化，S/MIMEはメールの暗号化や電子署名に用いる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-29','exam-sg','ハニーポット','standard','single_choice','【2019年度 令和元年秋期 午前 問29】ハニーポットの説明はどれか。','[{"id":"a","text":"サーバやネットワークを実際の攻撃に近い手法で検査し，実際に攻撃があった場合の被害範囲を予測する。"},{"id":"b","text":"社内ネットワークに接続するPCを事前に検査専用ネットワークで検査し，安全でないPCの接続を防ぐ。"},{"id":"c","text":"保護された領域で検査対象プログラムを動作させ，挙動からマルウェアを検出して隔離・駆除する。"},{"id":"d","text":"わざと侵入しやすいように設定した機器やシステムを配置し，攻撃手法やマルウェアの振る舞いを調査する。"}]','"d"','ハニーポットは攻撃者を誘い込むおとりのシステムで，攻撃の手法やマルウェアの挙動を観察する。ほかはペネトレーションテスト，検疫ネットワーク，サンドボックスの説明。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-30','exam-sg','ポートスキャナ','standard','single_choice','【2019年度 令和元年秋期 午前 問30】Webサーバの検査におけるポートスキャナの利用目的はどれか。','[{"id":"a","text":"Webサーバで稼働しているサービスを列挙し，不要なサービスが稼働していないことを確認する。"},{"id":"b","text":"Webサーバの利用者IDの管理状況を運用者に確認し，情報セキュリティポリシからの逸脱がないことを調べる。"},{"id":"c","text":"Webサーバへのアクセス履歴を解析して，不正利用を検出する。"},{"id":"d","text":"正規の利用者IDでログインし，Webサーバのコンテンツを直接確認して脆弱性を検出する。"}]','"a"','ポートスキャナは開いているポートや稼働サービスを調べ，不要なサービスや意図せず公開された入口を発見するために使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja');
